function setFS(id){FS=id;document.querySelectorAll('#terminal .tm-p').forEach(s=>s.classList.toggle('tm-fs',s.id===id));document.body.classList.toggle('tm-fs-on',!!id);if(id)setTimeout(()=>{draw();},50);else draw();}
function chartTip(e){const c=e.target,k=c.dataset.tip,r=c.getBoundingClientRect(),x=e.clientX-r.left;
 if(k==='chart'&&CH.chart){const{C,bw}=CH.chart,i=Math.floor(x/bw);if(i<0||i>=C.length)return tip();const q=C[i];return tip(e.clientX,e.clientY,`<b>${esc(PAIRS.find(p=>p[1]===sel)[2])} · ${TFL[TF]}</b><br>${new Date(q[0]*1000+7200e3).toISOString().slice(5,16).replace('T',' ')} SAST<br>O ${px(q[1])} H ${px(q[2])}<br>L ${px(q[3])} C <b>${px(q[4])}</b><br>vol ${(+q[6]).toPrecision(5)}`);}
 if(k==='lat'&&CH.lat){const{R,w}=CH.lat,i=Math.round(x/w*(R.length-1));const s=R[Math.max(0,Math.min(R.length-1,i))];return s?tip(e.clientX,e.clientY,`<b>Kraken RTT</b><br>${hm(s.at)} SAST · ${new Date(s.at+7200e3).toISOString().slice(0,10)}<br><b>${s.ms!=null?s.ms+' ms':'FAILED'}</b>`):tip();}
 if(k==='eq'&&CH.eq){const{eq,src}=CH.eq,w=r.width-46,i=Math.round(x/w*(eq.length-1));const j=Math.max(0,Math.min(eq.length-1,i));return tip(e.clientX,e.clientY,`<b>Paper equity</b><br>${esc(src[j]?.time_sast||'—')} SAST<br><b>${usd(eq[j])}</b> (${esc(src[j]?.version||'')})`);}}
function svgTip(e){const s=e.target.closest('svg.tmsk');if(!s||!s.dataset.v)return;const v=s.dataset.v.split(',').map(Number),r=s.getBoundingClientRect(),i=Math.max(0,Math.min(v.length-1,Math.round((e.clientX-r.left)/r.width*(v.length-1))));const lab=s.closest('[data-pair]')?.querySelector('b')?.textContent||s.previousElementSibling?.textContent||'series';tip(e.clientX,e.clientY,`<b>${esc(String(lab).slice(0,48))}</b><br>point ${i+1} of ${v.length}<br>value <b>${(+v[i]).toLocaleString(undefined,{maximumFractionDigits:4})}</b>`);}
function wireUI(el){
 el.addEventListener('click',e=>{const t=e.target;if(t.closest('[data-fsx]')){e.stopPropagation();setFS(null);return;}
  const tf=t.closest('[data-tf]');if(tf){TF=+tf.dataset.tf;render();chartFetch();return;}
  if(t.closest('[data-fl-reset]')){FL={side:'',coin:'',bot:'',sort:'time',dir:-1};render();return;}
  const so=t.closest('[data-sort]');if(so){const k=so.dataset.sort;FL.dir=FL.sort===k?-FL.dir:-1;FL.sort=k;render();return;}
  const b=t.closest('[data-bot]');if(b&&b.dataset.bot){openBot(b.dataset.bot);return;}
  const cn=t.closest('[data-coin]');if(cn){openCoin(cn.dataset.coin);return;}
  const p=t.closest('[data-pair]');if(p&&p.dataset.pair){pickCoin(p.dataset.pair);return;}
  const h=t.closest('[data-fs]');if(h&&PHONE()&&!t.closest('select,button,label')&&FS!==h.dataset.fs){setFS(h.dataset.fs);}});
 el.addEventListener('change',e=>{const s=e.target.closest('[data-fl]');if(s){FL[s.dataset.fl]=s.value;render();}});
 el.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]:not(button)')){e.preventDefault();e.target.click();}});
 el.addEventListener('pointermove',e=>{if(e.target.dataset?.tip)chartTip(e);else if(e.target.closest('svg.tmsk'))svgTip(e);else if(e.target.closest('[data-bot].tm-n'))tip(e.clientX,e.clientY,botTip(e.target.closest('[data-bot]').dataset.bot));else if(!e.target.closest('.tm-ring'))tip();});
 el.addEventListener('pointerleave',()=>tip());
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(DRW)closeDrawer();else if(FS)setFS(null);tip();}});}
